with lines as (select t.id, t.customer_id, t.created_at, line.product_id, line.qty, line.price, line.promo from carts t lateral view explode(t.items) x as line) select customer_id, date_trunc('day', created_at) as activity_day, min(created_at) as first_seen, count(case when promo = 'WELCOME5' then 1 end) as welcome5_count, sum(price) as total_price, approx_percentile(price, 0.95) as price_p95 from lines group by 1, 2 order by activity_day asc nulls last
